function makeMap(kind){const m={w:30,h:20,walls:Array(600).fill(false)};const rect=(x,y,w,h)=>{for(let j=y;j<y+h;j++)for(let i=x;i<x+w;i++)m.walls[j*m.w+i]=true};if(kind==='islands'){rect(9,5,3,9);rect(18,9,3,8);rect(18,3,6,2)}if(kind==='turn'){rect(14,0,2,13)}return m}
function resetScenario(){pause();map=makeMap($('#scenario').value);start={x:3,y:15,theta:0};goal={x:26,y:4,theta:0};$('#startAngle').value=0;$('#goalAngle').value=0;syncInputs();invalidate('地图已恢复，点击开始探索。')}
function syncInputs(){for(const [id,v]of Object.entries({sx:start.x,sy:start.y,gx:goal.x,gy:goal.y}))$('#'+id).value=v;$('#startAngleValue').textContent=Math.round(start.theta*180/Math.PI)+'°';$('#goalAngleValue').textContent=Math.round(goal.theta*180/Math.PI)+'°'}
function notify(s,error=false){$('#notice').textContent=s;$('#notice').classList.toggle('error',error)}
