function chooseMode(next){mode=next;const a=modes[mode];const lattice=mode==='lattice';for(const id of ['startAngle','goalAngle'])$('#'+id).step=lattice?45:15;if(lattice){start.theta=Math.round(start.theta/(Math.PI/4))*(Math.PI/4);goal.theta=Math.round(goal.theta/(Math.PI/4))*(Math.PI/4);$('#startAngle').value=Math.round(start.theta*180/Math.PI);$('#goalAngle').value=Math.round(goal.theta*180/Math.PI);syncInputs();}$('#algoTitle').textContent=a.name;$('#algoSubtitle').textContent=a.sub;$('#algoDescription').textContent=a.description;$('#modeTag').textContent=a.tag;$('#limitations').textContent=a.limit;$('#gLabel').textContent=mode.startsWith('nav-')?'累计势值 P':'累计代价 g';$('#poseControls').classList.toggle('visible',['hybrid','lattice'].includes(mode));document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode)});$('#stages').innerHTML=a.stages.map((s,i)=>`<button data-stage="${i}" title="计算后跳转到此阶段">${String(i+1).padStart(2,'0')} ${s}</button>`).join('');$('#stages').querySelectorAll('button').forEach(b=>b.onclick=()=>{pause();ensure();const phase=a.phases[+b.dataset.stage];let at=result.events.findIndex(e=>e.phase===phase||(phase==='smooth'&&e.phase==='orientation'));if(at<0){notify('该阶段没有执行：路径太短，或搜索未到达该阶段。',true);return}seek(at)});invalidate(lattice?'已切换到 Lattice：起终朝向对齐为 45° 档位，与内置基元匹配；位置保持一致。':'算法已切换。地图与起终点保持一致，便于比较。')}
function ensure(){if(result)return;const t=performance.now();result=L.plan(map,start,goal,mode,{weight:Number($('#weight').value)});result.computeMs=performance.now()-t;const highs={g:1,h:1,f:1};for(const e of result.events)for(const u of e.updates||[]){highs.g=Math.max(highs.g,u.v);highs.h=Math.max(highs.h,u.h);highs.f=Math.max(highs.f,u.f)}result.displayMax=Object.fromEntries(Object.entries(highs).map(([k,v])=>[k,Math.ceil(v/10)*10]));$('#scrub').max=result.events.length-1;seek(0);if(!result.success)notify('本次计算未找到路径。可播放过程，或点「查看结果」检查原因。',true)}
function apply(e){if(e.closed!==undefined){view.closed.add(e.closed);view.expanded++}view.changes=[];const pose=['hybrid','lattice'].includes(mode);for(const u of e.updates||[]){if(pose&&u.f>=view.fValues[u.id])continue;const before=view.values[u.id],beforeF=view.fValues[u.id],beforeH=view.hValues[u.id];if(before!==u.v||beforeF!==u.f||beforeH!==u.h){const existing=view.changes.find(c=>c.id===u.id);if(existing)Object.assign(existing,{after:u.v,afterF:u.f,afterH:u.h});else view.changes.push({id:u.id,before,after:u.v,beforeF,afterF:u.f,beforeH,afterH:u.h});view.values[u.id]=u.v;view.fValues[u.id]=u.f;view.hValues[u.id]=u.h}}if(e.path)view.path=e.path;if(e.raw)view.raw=e.raw;if(e.showGradient)view.gradient=true;view.current=e.current||null}
function activeLayer(){const selected=$('#valueLayer').value;if(!result||selected==='map')return 'map';if(selected!=='auto')return selected;return mode==='nav-dijkstra'||(mode.startsWith('nav-')&&view.gradient)?'g':'f'}
function displayValues(){const layer=activeLayer();return layer==='f'?view.fValues:layer==='h'?view.hValues:view.values}
function displayChanges(){const layer=activeLayer(),suffix=layer==='f'?'F':layer==='h'?'H':'';return view.changes.map(c=>({id:c.id,before:c['before'+suffix],after:c['after'+suffix]})).filter(c=>c.before!==c.after)}
function seek(n){if(!result)return;n=Math.max(0,Math.min(result.events.length-1,n));if(n<frame){clearView();frame=-1}for(let i=frame+1;i<=n;i++)apply(result.events[i]);frame=n;const e=result.events[frame];$('#stepTitle').textContent=e.title;$('#stepText').textContent=e.text;$('#stepPhase').textContent=({init:'初始化',search:'搜索进行中',los:'视线检查',gradient:'梯度计算',extract:'恢复路径',smooth:'位置平滑',orientation:'朝向处理',done:'已完成',failed:'未找到路径'})[e.phase];$('#stepCount').textContent='STEP '+String(frame+1).padStart(3,'0');$('#formula').textContent=e.formula||({done:'搜索 ≠ 路径恢复 ≠ 后处理',failed:'调整地图或起终点后重试',extract:mode.startsWith('nav-')?'p_next = p + step · normalize(−∇P)':'node ← parent(node)'})[e.phase]||'f(n) = g(n) + h(n)';$('#scrub').value=frame;updateMeta();draw();updateInspect();if(frame===result.events.length-1){pause();if(result.success){const len=result.path.reduce((v,p,i)=>v+(i?L.dist(p,result.path[i-1]):0),0);notify(`规划成功 · 搜索处理 ${result.expanded} 个状态 · 路径长 ${len.toFixed(1)} 格 · 浏览器计算 ${result.computeMs.toFixed(1)} ms（非 Nav2 基准）。`)}else notify(result.message,true)}}
function updateMeta(){const e=result?.events[frame];for(const id of ['g','h','f'])$('#'+id+'Value').textContent=Number.isFinite(e?.[id])?e[id].toFixed(1):'—';$('#progressLabel').textContent=playing?'正在逐步探索':result?'拖动时间线回看':'准备就绪';$('#progressCount').textContent=result?`${frame+1} / ${result.events.length}`:'0 / 0';$('#previous').disabled=!result||frame<=0;$('#canvasStatus').textContent=!result?'等待探索':e?.phase==='done'?'路径已恢复':e?.phase==='failed'?'未找到路径':`已处理 ${view.expanded} 个状态`;let stage=0;if(e){const ph=e.phase;stage=ph==='done'||ph==='failed'?2:ph==='extract'?1:ph==='smooth'||ph==='orientation'?2:ph==='gradient'?1:0;if(mode.startsWith('nav-')&&ph==='extract')stage=2}$('#stages').querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('active',result&&i===stage);b.classList.toggle('past',result&&i<stage)})}
