function point(p){return {x:(p.x+.5)*C,y:(p.y+.5)*C}}
function strokePath(p,color,width=3,dash=[]){if(!p?.length)return;ctx.beginPath();p.forEach((v,i)=>{const q=point(v);if(!i)ctx.moveTo(q.x,q.y);else ctx.lineTo(q.x,q.y)});ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineJoin='round';ctx.lineCap='round';ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([])}
function arrow(p,theta,color,len=11,width=1.6){const a=point(p),x=a.x+len*Math.cos(theta),y=a.y+len*Math.sin(theta);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(a.x-len*.35*Math.cos(theta),a.y-len*.35*Math.sin(theta));ctx.lineTo(x,y);ctx.moveTo(x-4*Math.cos(theta-.6),y-4*Math.sin(theta-.6));ctx.lineTo(x,y);ctx.lineTo(x-4*Math.cos(theta+.6),y-4*Math.sin(theta+.6));ctx.stroke()}
function marker(p,label,color){const center=point(p),small=$('#numbers').checked,q=small?{x:p.x*C+8,y:p.y*C+8}:center,r=small?7:14;ctx.beginPath();ctx.arc(q.x,q.y,r,0,Math.PI*2);ctx.fillStyle='#10282a';ctx.fill();ctx.lineWidth=small?1.6:2.5;ctx.strokeStyle=color;ctx.stroke();ctx.fillStyle=color;ctx.font='bold '+(small?8:12)+'px monospace';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,q.x,q.y+.5);if(['hybrid','lattice'].includes(mode)){const th=p.theta;ctx.strokeStyle=color;ctx.lineWidth=2.4;ctx.beginPath();ctx.moveTo(center.x+6*Math.cos(th),center.y+6*Math.sin(th));ctx.lineTo(center.x+17*Math.cos(th),center.y+17*Math.sin(th));ctx.stroke()}}
function numeric(v){return Number.isFinite(v)?v.toFixed(1):'∞'}
function valueColor(v,max){const colors=[[35,77,119],[39,125,134],[163,146,65],[204,72,41]],t=Math.max(0,Math.min(1,v/max))*3,k=Math.min(2,Math.floor(t)),f=t-k;return 'rgb('+colors[k].map((c,i)=>Math.round(c+(colors[k+1][i]-c)*f)).join(',')+')'}
function renderRanges(mapLayer,max){const swatch=(name,range,background)=>`<span class="range-item"><i style="background:${background}"></i><b>${range}</b><span>${name}</span></span>`;const blue='rgb(35,77,119)',teal='rgb(39,125,134)',gold='rgb(163,146,65)',red='rgb(204,72,41)';const ramp=(a,b)=>`linear-gradient(to right,${a},${b})`;$('#rangeGuide').innerHTML=mapLayer?swatch('自由空间','0',blue)+swatch('低膨胀代价','1–84',ramp(blue,teal))+swatch('中膨胀代价','85–168',ramp(teal,gold))+swatch('高膨胀代价','169–252',ramp(gold,red))+swatch('障碍 C','254','#64777a')+'<p>253：内切膨胀障碍；255：未知。本教学地图未生成这两类，因此没有对应着色。膨胀低／中／高是网页配色分段，不是 Nav2 的额外类型常量；当前示例膨胀最高 180。</p>':swatch('较低数值',`0–${(max/3).toFixed(1)}`,ramp(blue,teal))+swatch('中间数值',`${(max/3).toFixed(1)}–${(max*2/3).toFixed(1)}`,ramp(teal,gold))+swatch('较高数值',`${(max*2/3).toFixed(1)}–${max}`,ramp(gold,red))+swatch('地图障碍 C','254','#64777a')+swatch('尚未计算','∞','#182f30')+'<p>这些颜色区间只表示当前 f / g / h / P 的大小，不表示自由区或膨胀区；灰色 254 始终是地图障碍 C。分界显示到一位小数，颜色连续过渡。切到「地图代价 C」查看区域类型范围。</p>';$('#rangeGuide').classList.toggle('no-heat',!$('#heat').checked)}
function nextPreview(){if(!result||frame<0)return null;const e=result.events[frame+1];if(!e?.current)return null;return {x:e.current.x,y:e.current.y,theta:e.current.theta,title:e.title}}
function drawNextPreview(){const next=nextPreview(),hint=$('#nextNodeHint');if(!next){hint.textContent=!result?'开始探索后，绿色圆圈预告下一步处理的节点。':frame===result.events.length-1?'演示已结束，没有下一个节点。':`下一步：${result.events[frame+1]?.title||'结束'}（无单个处理节点）`;return}const q=point(next);ctx.beginPath();ctx.arc(q.x,q.y,16,0,Math.PI*2);ctx.strokeStyle='#46ef86';ctx.lineWidth=3;ctx.stroke();if(next.theta!==undefined&&$('#arrows').checked)arrow(next,next.theta,'#46ef86',12,1.8);const fmt=v=>Number.isInteger(v)?String(v):v.toFixed(2);hint.textContent=`下一步处理 (${fmt(next.x)}, ${fmt(next.y)}) · ${next.title}。绿色圆圈为预告，尚未执行更新。`}
