 $('#valueTitle').textContent=mapLayer?'地图通行代价 C':layer==='f'?(nav?'传播优先值 f = P + h':'搜索优先值 f = g + h'):layer==='h'?'启发估计 h':nav?'累计势值 P':'累计到达代价 g';$('#scaleMax').textContent=max;$('#valueHint').textContent=mapLayer?'C 是经过格子的局部代价；灰色障碍显示 254，不参与 0–252 色标。':(layer==='f'?'f 用于比较待探索节点的优先级；已处理格子的历史 f 也保留显示。':layer==='h'?'h 是算法实际使用的剩余代价估计，Dijkstra 的 h=0。':nav?'P 是用于梯度提取的势场；不是传播优先值 f。':'g 是从起点到当前节点的累计代价。')+(['hybrid','lattice'].includes(mode)?' 同格取已发现状态中 f 最小的代表位姿，g、h、f 属于同一状态。':'')+' 蓝色低 → 橙红色高；∞ 尚未计算，色标整轮固定。';$('.color-scale').classList.toggle('disabled',!heat);renderRanges(mapLayer,max);
 $('#updateDetails').textContent=!result?'开始探索后，每个格子的数字会随步骤更新。':mapLayer?'地图代价 C 不随搜索变化；切换 f / g / h 查看搜索更新。':changes.length?`本步更新 ${changes.length} 格：`+changes.map(c=>`(${c.id%30},${Math.floor(c.id/30)}) ${numeric(c.before)} → ${numeric(c.after)}`).join('  ·  '):'本步没有当前显示量的数值更新。';
 for(let y=0;y<20;y++)for(let x=0;x<30;x++){const id=y*30+x,wall=m.walls[id],v=mapLayer?m.cost[id]:values[id];ctx.fillStyle=wall?'#64777a':heat&&Number.isFinite(v)?valueColor(v,max):'#182f30';ctx.fillRect(x*C+1,y*C+1,C-2,C-2);if(!wall&&view.closed.has(id)){ctx.fillStyle='#c9fbe9';ctx.fillRect(x*C+3,y*C+3,3,3)}if(wall){ctx.fillStyle='#7e9290';ctx.fillRect(x*C+3,y*C+3,C-6,2)}if(!wall&&changed.has(id)){ctx.strokeStyle='#ffdb67';ctx.lineWidth=2.5;ctx.strokeRect(x*C+2.5,y*C+2.5,C-5,C-5)}}
 ctx.strokeStyle='#bdd4c209';ctx.lineWidth=1;for(let x=0;x<=30;x++){ctx.beginPath();ctx.moveTo(x*C,0);ctx.lineTo(x*C,H);ctx.stroke()}for(let y=0;y<=20;y++){ctx.beginPath();ctx.moveTo(0,y*C);ctx.lineTo(W,y*C);ctx.stroke()}
 if(view.gradient&&arrows&&result?.gradients)result.gradients.forEach((g,id)=>{if(g&&Number.isFinite(view.values[id])&&!m.walls[id]&&Math.hypot(g.x,g.y)>.1)arrow({x:id%30,y:Math.floor(id/30)},Math.atan2(g.y,g.x),numbers?'#d9ecc44d':'#b9d8a26b',10,1)});
 const e=result?.events[frame];if(e){for(const p of e.neighbors||[]){if(L.free(m,p.x,p.y)){ctx.strokeStyle='#f5d38d55';ctx.lineWidth=1.5;ctx.strokeRect(p.x*C+4,p.y*C+4,C-8,C-8)}}for(const a of e.candidates||[])strokePath(a.points,a.ok?'#7be0ce':'#ef927f77',2.5);for(const a of e.edges||[])strokePath([a.from,a.to],'#8de2c96b',1.5);if(e.los)strokePath([e.los.from,e.los.to],e.accepted?'#c8f691':'#ed927e',3,[7,5])}
 if(view.raw.length)strokePath(view.raw,'#c0cbae66',2,[5,6]);if(view.path.length){strokePath(view.path,'#e4f7ac',4);if(arrows&&(e?.phase==='orientation'||e?.phase==='done'||['hybrid','lattice'].includes(mode))){const step=Math.max(1,Math.floor(view.path.length/25));view.path.forEach((p,i)=>{if(i%step===0&&i<view.path.length-1){const n=view.path[i+1],th=p.theta??Math.atan2(n.y-p.y,n.x-p.x);arrow(p,th,'#f3ffe1',9,1.4)}})}}
