 if(numbers){ctx.textAlign='center';ctx.textBaseline='middle';for(let y=0;y<20;y++)for(let x=0;x<30;x++){const id=y*30+x,wall=m.walls[id],v=mapLayer?m.cost[id]:values[id],text=wall?'254':mapLayer?String(v):numeric(v);ctx.font=(changed.has(id)?'bold ':'')+'14px monospace';ctx.lineWidth=3;ctx.strokeStyle='#102125dc';ctx.fillStyle=wall?'#d4dfdf':changed.has(id)?'#ffe88d':Number.isFinite(v)?'#fffef0':'#799493';const tx=(x+.5)*C,ty=y*C+24;ctx.strokeText(text,tx,ty,C-4);ctx.fillText(text,tx,ty,C-4)}}
