function updateInspect(){if(!selected)return;const id=selected.y*30+selected.x,m=result?.map||L.prepare(map),g=view.values[id],h=view.hValues[id],f=view.fValues[id],detail=v=>Number.isFinite(v)?v.toFixed(3):'∞';$('#cellPosition').textContent=`(${selected.x}, ${selected.y})`;$('#cellDetails').textContent=m.walls[id]?'C=254 · 障碍物 · 不可通行':`C=${m.cost[id]} · ${mode.startsWith('nav-')?'P':'g'}=${detail(g)} · h=${detail(h)} · f=${detail(f)} · ${view.closed.has(id)?'已处理':'未处理'}${['hybrid','lattice'].includes(mode)?'（最小 f 代表位姿）':''}`}
function canvasCell(e){const r=canvas.getBoundingClientRect();return {x:Math.min(29,Math.max(0,Math.floor((e.clientX-r.left)/r.width*30))),y:Math.min(19,Math.max(0,Math.floor((e.clientY-r.top)/r.height*20)))}}
function edit(p){if(tool==='inspect'){selected=p;updateInspect();draw();return}if(tool==='wall'||tool==='erase'){if((p.x===start.x&&p.y===start.y)||(p.x===goal.x&&p.y===goal.y))return;const id=p.y*30+p.x,v=tool==='wall';if(map.walls[id]===v)return;map.walls[id]=v;invalidate('地图已编辑，旧搜索已清空。');return}if(map.walls[p.y*30+p.x]){notify('端点不能放在障碍物中。请先擦除障碍，或选择空闲格子。',true);return}if(tool==='start')start={...start,...p};else goal={...goal,...p};syncInputs();invalidate(`${tool==='start'?'起点':'目标'}已设为 (${p.x}, ${p.y})，可重新开始探索。`)}
