$('#tools').querySelectorAll('button').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;canvas.classList.toggle('drawing',['wall','erase'].includes(tool));$('#tools').querySelectorAll('button').forEach(a=>{a.classList.toggle('active',a===b);a.setAttribute('aria-pressed',a===b)});notify(tool==='inspect'?'点击格子查看当前代价与状态。':tool==='wall'||tool==='erase'?'在地图上点击或拖动编辑障碍。':`点击一个空闲格子设置${tool==='start'?'起点':'目标'}。`)});
canvas.addEventListener('pointerdown',e=>{const p=canvasCell(e);if(e.pointerType==='touch'&&!['wall','erase'].includes(tool)){touchTap={x:e.clientX,y:e.clientY,cell:p,moved:false};return}pointerDown=true;lastPaint=p;canvas.setPointerCapture(e.pointerId);edit(p)});
canvas.addEventListener('pointermove',e=>{const p=canvasCell(e),m=result?.map||L.prepare(map);$('#hoverInfo').textContent=`x ${String(p.x).padStart(2,'0')} · y ${String(p.y).padStart(2,'0')} · cost ${m.cost[p.y*30+p.x]}`;if(touchTap&&Math.hypot(e.clientX-touchTap.x,e.clientY-touchTap.y)>8)touchTap.moved=true;if(pointerDown&&['wall','erase'].includes(tool)&&(!lastPaint||p.x!==lastPaint.x||p.y!==lastPaint.y)){lastPaint=p;edit(p)}});
canvas.addEventListener('pointerup',()=>{pointerDown=false;if(touchTap&&!touchTap.moved)edit(touchTap.cell);touchTap=null});canvas.addEventListener('pointercancel',()=>{pointerDown=false;touchTap=null});
$('#play').onclick=()=>{if(playing){pause();updateMeta();return}ensure();if(frame>=result.events.length-1)seek(0);playing=true;$('#play').textContent='Ⅱ 暂停';updateMeta();tick()};$('#next').onclick=()=>{pause();ensure();seek(frame+1)};$('#previous').onclick=()=>{pause();seek(frame-1)};$('#finish').onclick=()=>{pause();ensure();seek(result.events.length-1)};$('#reset').onclick=()=>{pause();if(result)seek(0);else invalidate()};$('#scrub').oninput=e=>{pause();if(result)seek(Number(e.target.value))};$('#speed').onchange=()=>{if(playing){clearTimeout(timer);timer=setTimeout(tick,1000/Number($('#speed').value))}};$('#scenario').onchange=resetScenario;$('#restore').onclick=resetScenario;$('#heat').onchange=draw;$('#numbers').onchange=draw;$('#valueLayer').onchange=()=>{draw();updateInspect()};$('#arrows').onchange=draw;$('#weight').onchange=()=>invalidate('代价权重已修改，重新计算会使用新权重。');
for(const id of ['sx','sy','gx','gy'])$('#'+id).onchange=()=>{const isS=id[0]==='s',axis=id[1],v=Number($('#'+id).value),p={...(isS?start:goal),[axis]:v};if(!Number.isInteger(v)||v<0||v>=(axis==='x'?30:20)||map.walls[p.y*30+p.x]){syncInputs();notify('坐标需要在地图范围内，并且位于空闲格子。',true);return}if(isS)start=p;else goal=p;invalidate('坐标已更新，旧搜索已清空。')};
