document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA','BUTTON','SUMMARY'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();$('#play').click()}if(e.code==='ArrowRight'){$('#next').click();e.preventDefault()}if(e.code==='ArrowLeft'){$('#previous').click();e.preventDefault()}});
